```kotlin
class RoomCorrector(..., private val fastTwoBandCorrection: Boolean = true)

fun computeCorrections(referenceLevels, measuredLevels, currentBands): List<EqBand> {
    val now = System.currentTimeMillis()
    if (fastTwoBandCorrection && now - lastCorrectionMs < TWO_BAND_PERIOD_MS) {
        return currentBands
    }
    lastCorrectionMs = now

    val deviations = FloatArray(currentBands.size) { i ->
        val ref = if (i < referenceLevels.size) referenceLevels[i] else 0f
        val meas = if (i < measuredLevels.size) measuredLevels[i] else 0f
        meas - ref
    }

    // Find highest (most positive) and lowest (most negative) deviation
    var maxIdx = -1; var minIdx = -1
    for (i in deviations.indices) {
        if (maxIdx == -1 || deviations[i] > deviations[maxIdx]) maxIdx = i
        if (minIdx == -1 || deviations[i] < deviations[minIdx]) minIdx = i
    }

    val result = currentBands.toMutableList()
    if (maxIdx >= 0) result[maxIdx] = applyCorrection(result[maxIdx], -deviations[maxIdx], maxIdx)
    if (minIdx >= 0 && minIdx != maxIdx) result[minIdx] = applyCorrection(result[minIdx], -deviations[minIdx], minIdx)
    return result
}

private fun applyCorrection(band: EqBand, rawCorrection: Float, idx: Int): EqBand {
    val clamped = rawCorrection.coerceIn(-maxGainDb, maxGainDb)
    val smoothed = previousGains[idx] * (1f - smoothingFactor) + clamped * smoothingFactor
    previousGains[idx] = smoothed
    return band.copy(targetGainDb = clamped, gainDb = smoothed)
}
```

