        synchronized(lock) { activeTracks[outputId] = track }
        track.play()
        return true
    }

    fun stop(outputId: String) { synchronized(lock) { activeTracks.remove(outputId) }?.let { release(it) } }
    fun stopAll() { synchronized(lock) { val all = activeTracks.values.toList(); activeTracks.clear(); all }.forEach { release(it) } }
    private fun release(track: AudioTrack) { try { track.pause(); track.flush(); track.release() } catch (e: IllegalStateException) {} }
}
