private fun resolveOutputDevice(type: DeviceType): AudioDeviceInfo? {
    val am = getApplication<Application>().getSystemService(Context.AUDIO_SERVICE) as? AudioManager ?: return null
    val outputs = am.getDevices(AudioManager.GET_DEVICES_OUTPUTS)
    return when (type) {
        DeviceType.PHONE, DeviceType.TABLET -> outputs.firstOrNull { it.type == AudioDeviceInfo.TYPE_BUILTIN_SPEAKER }
        DeviceType.BLUETOOTH_SPEAKER -> outputs.firstOrNull { it.type == AudioDeviceInfo.TYPE_BLUETOOTH_A2DP }
        DeviceType.USB_AUDIO -> outputs.firstOrNull {
            it.type == AudioDeviceInfo.TYPE_USB_DEVICE || it.type == AudioDeviceInfo.TYPE_USB_HEADSET
        }
        DeviceType.IN_EARS, DeviceType.MONITOR -> outputs.firstOrNull {
            it.type == AudioDeviceInfo.TYPE_WIRED_HEADPHONES || it.type == AudioDeviceInfo.TYPE_WIRED_HEADSET
        }
        else -> null
    }
}
